133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        List<String> missingFields = new ArrayList<>();
137	        if (isBlank(ownerFieldsDto.getFirstName())) {
138	            missingFields.add("firstName");
139	        }
140	        if (isBlank(ownerFieldsDto.getLastName())) {
141	            missingFields.add("lastName");
142	        }
143	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
144	        if (isBlank(normalizedAddress)) {
145	            missingFields.add("address");
146	        }
147	        if (isBlank(ownerFieldsDto.getCity())) {
148	            missingFields.add("city");
149	        }
150	        if (isBlank(ownerFieldsDto.getTelephone())) {
151	            missingFields.add("telephone");
152	        }
153	        if (!missingFields.isEmpty()) {
154	            throw new MissingOwnerFieldsException(missingFields);
155	        }
156	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
157	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
158	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
159	            throw new FutureRegistrationDateException(
160	                "registrationDate must not be later than the server date");
161	        }
162	        LocalDate registrationDate = toBusinessDay(
163	            suppliedRegistrationDate != null
164	                ? suppliedRegistrationDate
165	                : LocalDate.now());
166	        long registeredOnDay = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
168	            .count();
169	        if (registeredOnDay >= 100) {
170	            throw new DailyRegistrationLimitException(
171	                "100 or more owners have already been registered today");
172	        }
173	        boolean bulkSignupWarning = registeredOnDay > 80;
174	        String city = ownerFieldsDto.getCity();
175	        long ownersInCity = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
177	            .count();
178	        if (ownersInCity >= 50) {
179	            throw new CityAtCapacityException(
180	                "the owner's city already contains 50 or more owners");
181	        }
182	        ownerFieldsDto.setAddress(normalizedAddress);
183	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
184	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
185	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
186	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
187	            .toList();
188	        String householdId = null;
189	        if (!householdMembers.isEmpty()) {
190	            // Owners sharing a normalized last name and address form a household with a
191	            // stable shared identifier; backfill any members created before it was formed.
192	            // The household id is part of the identity key, so two members with different
193	            // telephones have different identity keys and are both allowed.
194	            householdId = householdId(lastName, normalizedAddress);
195	            for (Owner member : householdMembers) {
196	                if (!householdId.equals(member.getHouseholdId())) {
197	                    member.setHouseholdId(householdId);
198	                    this.clinicService.saveOwner(member);
199	                }
200	            }
201	        }
202	        String telephone = toE164(ownerFieldsDto.getTelephone());
203	        ownerFieldsDto.setTelephone(telephone);
204	        String email = normalizeEmail(ownerFieldsDto.getEmail());
205	        ownerFieldsDto.setEmail(email);
206	        // Single, consolidated duplicate check: reject only when the new owner's whole
207	        // derived identity key (telephone|email|householdId) equals an existing owner's.
208	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
209	        boolean identityInUse = this.clinicService.findAllOwners().stream()
210	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
211	                existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
212	        if (identityInUse) {
213	            throw new DuplicateIdentityException(
214	                "an owner with the same identity key already exists");
215	        }
216	        // Soft (possible) duplicate: not a hard duplicate, but sharing an existing owner's
217	        // last name and postcode with a different telephone. The owner is still created; it is
218	        // flagged and carries the matching owner's id (the lowest when several match).
219	        String postcode = ownerFieldsDto.getPostcode();
220	        Integer possibleDuplicateOf = null;
221	        if (!isBlank(postcode)) {
222	            possibleDuplicateOf = this.clinicService.findAllOwners().stream()
223	                .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
224	                    && postcode.equals(existing.getPostcode())
225	                    && !telephone.equals(existing.getTelephone()))
226	                .map(Owner::getId)
227	                .min(Comparator.naturalOrder())
228	                .orElse(null);
229	        }
230	        HttpHeaders headers = new HttpHeaders();
231	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
232	        owner.setRegistrationDate(registrationDate);
233	        owner.setCustomerCode(
234	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
235	        owner.setHouseholdId(householdId);
236	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
237	        owner.setBulkSignupWarning(bulkSignupWarning);
238	        // Household size after this create: existing members plus the owner being created.
239	        owner.setHouseholdSize(householdMembers.size() + 1);
240	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
241	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
242	        this.clinicService.saveOwner(owner);
243	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
244	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
245	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
246	            ownerDto.getMembershipLevel());
247	        headers.setLocation(UriComponentsBuilder.newInstance()
248	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
249	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
250	    }
