252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
255	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
256	        if (currentOwner == null) {
257	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	        }
259	        currentOwner.setAddress(ownerFieldsDto.getAddress());
260	        currentOwner.setCity(ownerFieldsDto.getCity());
261	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
262	        currentOwner.setLastName(ownerFieldsDto.getLastName());
263	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
264	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
265	        this.clinicService.saveOwner(currentOwner);
266	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
267	    }
