346	    private static boolean isBlank(String value) {
347	        return value == null || value.isBlank();
348	    }
349	
350	    /**
351	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
352	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
353	     * to the effective registration date (whether supplied in the request or defaulted to the server
354	     * date), so every value derived from the registration date sees the adjusted business day.
355	     */
356	    private static LocalDate toBusinessDay(LocalDate date) {
357	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
358	            date = date.plusDays(1);
359	        }
360	        return date;
361	    }
362	
363	    /**
364	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
365	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
366	     * lower-cased so that last names are compared case-insensitively.
367	     */
368	    private static String normalizeHousehold(String value) {
369	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
370	    }
371	
372	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
373	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
374	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
375	
376	    /**
377	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
378	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
379	     * upper-cased, and common street-type abbreviations are expanded token-by-token
380	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
381	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
382	     * used for every address comparison (household-duplicate detection and the shared household id).
383	     */
384	    private static String normalizeAddress(String value) {
385	        if (value == null) {
386	            return "";
387	        }
388	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
389	        if (collapsed.isEmpty()) {
390	            return "";
391	        }
392	        String[] tokens = collapsed.split(" ");
393	        StringBuilder sb = new StringBuilder();
394	        for (int i = 0; i < tokens.length; i++) {
395	            if (i > 0) {
396	                sb.append(' ');
397	            }
398	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
399	        }
400	        return sb.toString();
401	    }
402	
403	    /**
404	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
405	     * deterministic function of the normalized last name and address, so every owner that
406	     * shares those values maps to the same identifier regardless of creation order.
407	     */
408	    private static String householdId(String normalizedLastName, String normalizedAddress) {
409	        String key = normalizedLastName + "\n" + normalizedAddress;
410	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
411	    }
412	
413	    /**
414	     * Builds the {@code customerCode} assigned to a new owner, formatted
415	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
416	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
417	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
418	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
419	     * pure function of the owner's own identity fields.
420	     */
421	    private static String customerCode(String postcode, String telephone, String lastName) {
422	        String region = LocalityDeriver.region(postcode);
423	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
424	            + (lastName == null ? "" : lastName));
425	        return region + "-" + hash8;
426	    }
427	
428	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
429	    private static String sha256Hex8(String s) {
430	        try {
431	            byte[] digest = MessageDigest.getInstance("SHA-256")
432	                .digest(s.getBytes(StandardCharsets.UTF_8));
433	            StringBuilder sb = new StringBuilder(8);
434	            for (int i = 0; i < 4; i++) {
435	                sb.append(String.format("%02X", digest[i]));
436	            }
437	            return sb.toString();
438	        }
439	        catch (NoSuchAlgorithmException e) {
440	            throw new IllegalStateException("SHA-256 not available", e);
441	        }
442	    }
443	
444	    /**
445	     * Counts the existing owners that share the given first name and last name, compared
446	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
447	     * owner currently being created is saved), so it reflects how many namesakes preceded the
448	     * new owner.
449	     */
450	    private int countNamesakes(String firstName, String lastName) {
451	        return (int) this.clinicService.findAllOwners().stream()
452	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
453	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
454	            .count();
455	    }
456	
457	    /**
458	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
459	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
460	     * national one, a single leading {@code '0'} is dropped, and the default country code
461	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
462	     * national number must have the length required by its country code ({@code '+61'} requires 9
463	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
464	     * raised (reported to the client as 400).
465	     */
466	    private static String toE164(String telephone) {
467	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
468	        String digits;
469	        if (cleaned.startsWith("+")) {
470	            digits = cleaned.substring(1);
471	        } else {
472	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
473	            digits = "61" + national;
474	        }
475	        if (!digits.matches("[0-9]{8,15}")) {
476	            throw new InvalidTelephoneException(
477	                "telephone must form a valid E.164 number with 8 to 15 digits");
478	        }
479	        validateNationalLength(digits);
480	        return "+" + digits;
481	    }
482	
483	    /** National-number length required for each supported country code (digits after the code). */
484	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
485	        "61", 9, "1", 10);
486	
487	    /**
488	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
489	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
490	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
491	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
492	     */
493	    private static void validateNationalLength(String digits) {
494	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
495	            String code = entry.getKey();
496	            if (digits.startsWith(code)) {
497	                int nationalLength = digits.length() - code.length();
498	                if (nationalLength != entry.getValue()) {
499	                    throw new InvalidTelephoneException(
500	                        "telephone national number must have " + entry.getValue()
501	                            + " digits for country code +" + code);
502	                }
503	                return;
504	            }
505	        }
506	    }
507	
508	    /**
509	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
510	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
511	     * any 4-digit postcode.
512	     */
513	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
514	        "NSW", new int[] {2000, 2099},
515	        "VIC", new int[] {3000, 3099},
516	        "QLD", new int[] {4000, 4099});
517	
518	    /**
519	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
520	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
521	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
522	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
523	     * no known region accepts any 4-digit postcode. A violation raises an
524	     * {@link InvalidPostcodeException} (reported to the client as 400).
525	     */
526	    private static void validatePostcode(String city, String postcode) {
527	        if (isBlank(postcode)) {
528	            return;
529	        }
530	        if (!postcode.matches("[0-9]{4}")) {
531	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
532	        }
533	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
534	        if (range == null) {
535	            return;
536	        }
537	        int value = Integer.parseInt(postcode);
538	        if (value < range[0] || value > range[1]) {
539	            throw new InvalidPostcodeException(
540	                "postcode is out of range for the owner's city region");
541	        }
542	    }
543	
544	    /**
545	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
546	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
547	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
548	     * stored and returned in canonical form.
549	     */
550	    private static String normalizeEmail(String email) {
551	        if (isBlank(email)) {
552	            return null;
553	        }
554	        String trimmed = email.trim();
555	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
556	            throw new InvalidEmailException("email must be a syntactically valid address");
557	        }
558	        return trimmed.toLowerCase(Locale.ROOT);
559	    }
560	}
